#include "asm/field_script.inc"
#include "hoenn.h"  // ch6
#include "hoenn_story.inc"  // ch6

    ScriptEntry Script_1
    ScriptEntry Script_2
    ScriptEntry Story_H2_FanClub   // 3: object 1 (the Fan Club Chairman's younger brother)  // story:
    ScriptEntry Story_H2_HappyAzurill   // 4: object 2  // story:
    ScriptEntry Story_H2_UnhappyAzurill   // 5: object 3  // story:
    ScriptEntriesEnd

Script_1:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    SystemMsg 0, 2
    LastKeyWait
    MsgWinCloseAll
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt

Script_2:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    SystemMsg 1, 2
    LastKeyWait
    MsgWinCloseAll
    FinishAllEvents
    ActorsUnpauseAll
