// ---- story (chapter Ch12, ch6 agent: Sapphire data/maps/PacifidlogTown_House2/scripts.inc; generators keep everything
// from this line on). People: data/story/ch12.json (uid = Sapphire local id). Text lines 2-13 of the text file.
// The weekly TM: Sapphire counts days with the save's day counter (gLocalTime.days: GetDaysUntilPacifidlogTMAvailable,
// SetPacifidlogTMReceivedDay). Black 2's scripts only read the date (RTCGetDate), so the day count is the day of the
// year (1-366) and a year turning over adds 365: the same 7-day wait. The Return/Frustration TMs are Black 2's TM27 /
// TM21 (the same numbers and moves as Sapphire's).
// GetLeadMonFriendshipScore: the first party Pokémon that is not an Egg, Sapphire's thresholds (255/200/150/100/50/1:
// score 6..1; 4 or more = Return, 2 or 3 = "put in some more effort", else Frustration).
#define T_BROTHER 2
#define T_AHYOURMON 3
#define T_ADORING 4
#define T_EFFORT 5
#define T_VICIOUS 6
#define T_EXPLAIN 7
#define T_INDAYS 8
#define T_RURII 9
#define T_HAPPYFRIEND 10
#define T_RURURI 11
#define T_UNHAPPY 12
#define T_BAGFULL 13
#define H2_MONTH 0x8020
#define H2_DAY 0x8021
#define H2_TODAY 0x8022
#define H2_ELAPSED 0x8023
#define H2_LEAD 0x8024
#define H2_FRIEND 0x8025

H2_Days:                                    // GetDaysUntilPacifidlogTMAvailable: HLIB_RESULT = days left (0 = a week is up)
    RTCGetDate H2_MONTH, H2_DAY
    WorkSetConst H2_TODAY, 0
    h_goto_if_lt H2_MONTH, 2, L_H2_Sum
    h_addvar H2_TODAY, 31                   // January
    h_goto_if_lt H2_MONTH, 3, L_H2_Sum
    h_addvar H2_TODAY, 28
    h_goto_if_lt H2_MONTH, 4, L_H2_Sum
    h_addvar H2_TODAY, 31
    h_goto_if_lt H2_MONTH, 5, L_H2_Sum
    h_addvar H2_TODAY, 30
    h_goto_if_lt H2_MONTH, 6, L_H2_Sum
    h_addvar H2_TODAY, 31
    h_goto_if_lt H2_MONTH, 7, L_H2_Sum
    h_addvar H2_TODAY, 30
    h_goto_if_lt H2_MONTH, 8, L_H2_Sum
    h_addvar H2_TODAY, 31
    h_goto_if_lt H2_MONTH, 9, L_H2_Sum
    h_addvar H2_TODAY, 31
    h_goto_if_lt H2_MONTH, 10, L_H2_Sum
    h_addvar H2_TODAY, 30
    h_goto_if_lt H2_MONTH, 11, L_H2_Sum
    h_addvar H2_TODAY, 31
    h_goto_if_lt H2_MONTH, 12, L_H2_Sum
    h_addvar H2_TODAY, 30
L_H2_Sum:
    WorkAdd H2_TODAY, H2_DAY
    WorkSet H2_ELAPSED, H2_TODAY
    WorkCmpWork H2_TODAY, VAR_PACIFIDLOG_TM_RECEIVED_DAY
    VMJumpIf CMP_LT, L_H2_Wrap
    WorkSub H2_ELAPSED, VAR_PACIFIDLOG_TM_RECEIVED_DAY
    VMJump L_H2_Elapsed
L_H2_Wrap:                                  // the year turned over since the TM was given
    WorkAdd H2_ELAPSED, 365
    WorkSub H2_ELAPSED, VAR_PACIFIDLOG_TM_RECEIVED_DAY
L_H2_Elapsed:
    h_goto_if_ge H2_ELAPSED, 7, L_H2_WeekUp
    WorkSetConst HLIB_RESULT, 7
    WorkSub HLIB_RESULT, H2_ELAPSED
    VMReturn
L_H2_WeekUp:
    WorkSetConst HLIB_RESULT, 0
    VMReturn

H2_SetReceivedDay:                          // SetPacifidlogTMReceivedDay
    VMCall H2_Days                          // (sets H2_TODAY)
    WorkSet VAR_PACIFIDLOG_TM_RECEIVED_DAY, H2_TODAY
    VMReturn

Story_H2_FanClub:                           // PacifidlogTown_House2_EventScript_FanClubYoungerBrother
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_unset FLAG_RECEIVED_FANCLUB_TM_THIS_WEEK, L_H2_Assess
    VMCall H2_Days                          // UpdateFanClubTMFlag
    h_goto_if_ne HLIB_RESULT, 0, L_H2_ComeBack
    h_clearflag FLAG_RECEIVED_FANCLUB_TM_THIS_WEEK
L_H2_Assess:
    h_goto_if_set FLAG_MET_FANCLUB_YOUNGER_BROTHER, L_H2_Met
    h_msgbox T_BROTHER                      // Er-hem! I am the Pokémon Fan Club's most important person, ...
L_H2_Met:
    h_msgbox T_AHYOURMON                    // Ah! Your Pokémon...
    h_setflag FLAG_MET_FANCLUB_YOUNGER_BROTHER
    h_get_lead_mon H2_LEAD
    PokePartyGetHappiness H2_FRIEND, H2_LEAD
    h_goto_if_ge H2_FRIEND, 150, L_H2_GiveReturn      // score 4-6
    h_goto_if_ge H2_FRIEND, 50, L_H2_PutInEffort      // score 2-3
    h_msgbox T_VICIOUS                      // GiveFrustration: It has a vicious look to it. ...
    h_closemessage                          // (Black 2: the item script opens its own window)
    h_giveitem ITEM_TM21                    // Black 2's TM21 is Frustration too
    h_goto_if_eq HLIB_RESULT, 0, L_H2_BagFull
    VMJump L_H2_Gave
L_H2_GiveReturn:
    h_msgbox T_ADORING                      // It clearly likes you very much. ...
    h_closemessage
    h_giveitem ITEM_TM27                    // Black 2's TM27 is Return too
    h_goto_if_eq HLIB_RESULT, 0, L_H2_BagFull
L_H2_Gave:
    h_setflag FLAG_RECEIVED_FANCLUB_TM_THIS_WEEK
    VMCall H2_SetReceivedDay
    h_msgbox T_EXPLAIN                      // If a Pokémon likes you a lot, Return's power is enhanced. ...
    h_release
L_H2_PutInEffort:
    h_msgbox T_EFFORT                       // Hmm... It's not bad, but it's also not good. ...
    h_release
L_H2_ComeBack:                              // ComeBackInXDays
    WordSetNumber 1, HLIB_RESULT, 1
    h_msgbox T_INDAYS                       // Oh, yes. In about {1} or so days, I should be getting a good TM or two. ...
    h_release
L_H2_BagFull:                               // Common_EventScript_ShowBagIsFull
    h_bag_is_full T_BAGFULL
    h_release

Story_H2_HappyAzurill:                      // PacifidlogTown_House2_EventScript_HappyAzurill
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_waitse
    h_playmoncry SPECIES_AZURILL
    h_msgbox T_RURII                        // Azurill: Rurii.
    h_waitmoncry
    h_msgbox T_HAPPYFRIEND                  // It appears to be very friendly with the Trainer.
    h_release

Story_H2_UnhappyAzurill:                    // PacifidlogTown_House2_EventScript_UnhappyAzurill
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_waitse
    h_playmoncry SPECIES_AZURILL            // (Sapphire's mode 2 cry: Black 2's PVPlay has one cry)
    h_msgbox T_RURURI                       // Azurill: Rururi!
    h_waitmoncry
    h_msgbox T_UNHAPPY                      // It doesn't appear to like the Trainer very much.
    h_release
    .balign 4, 0
